        { $group: { _id: '$role', count: { $sum: 1 } } }
      ],
      cityBreakdown: [
        { $match: { city: { $exists: true, $ne: null } } },
        { $group: { _id: '$city', count: { $sum: 1 } } },
        { $sort: { count: -1 } },
        { $limit: 10 }
      ]
    }
  }
]) }}

