// Fetch social media stats via their APIs
// This node aggregates follower counts and engagement rates

const platforms = {
  facebook: {
    pageId: process.env.FB_PAGE_ID || 'DARSY_FB_PAGE_ID',
    accessToken: process.env.FB_ACCESS_TOKEN || 'FB_TOKEN'
  },
  instagram: {
    accountId: process.env.IG_ACCOUNT_ID || 'DARSY_IG_ACCOUNT_ID',
    accessToken: process.env.IG_ACCESS_TOKEN || 'IG_TOKEN'
  },
  tiktok: {
    username: 'darsy_dz'
  },
  youtube: {
    channelId: process.env.YT_CHANNEL_ID || 'DARSY_YT_CHANNEL_ID',
    apiKey: process.env.YT_API_KEY || 'YT_KEY'
  }
};

try {
  // Facebook Page Insights
  const fbResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://graph.facebook.com/v18.0/${platforms.facebook.pageId}`,
    qs: {
      fields: 'followers_count,fan_count,talking_about_count',
      access_token: platforms.facebook.accessToken
    }
  });

  // Instagram Business Account Insights
  const igResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://graph.facebook.com/v18.0/${platforms.instagram.accountId}`,
    qs: {
      fields: 'followers_count,media_count,profile_views',
      access_token: platforms.instagram.accessToken
    }
  });

  // YouTube Channel Stats
  const ytResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.googleapis.com/youtube/v3/channels',
    qs: {
      part: 'statistics',
      id: platforms.youtube.channelId,
      key: platforms.youtube.apiKey
    }
  });

  return [{
    json: {
      facebook: {
        followers: fbResponse.followers_count || 0,
        fans: fbResponse.fan_count || 0,
        talkingAbout: fbResponse.talking_about_count || 0
      },
      instagram: {
        followers: igResponse.followers_count || 0,
        mediaCount: igResponse.media_count || 0
      },
      youtube: {
        subscribers: ytResponse.items?.[0]?.statistics?.subscriberCount || 0,
        totalViews: ytResponse.items?.[0]?.statistics?.viewCount || 0,
        videoCount: ytResponse.items?.[0]?.statistics?.videoCount || 0
      },
      fetchedAt: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{
    json: {
      error: 'Some social media APIs failed',
      message: error.message,
      facebook: { followers: 0, note: 'API call failed' },
      instagram: { followers: 0, note: 'API call failed' },
      youtube: { subscribers: 0, note: 'API call failed' },
      fetchedAt: new Date().toISOString()
    }
  }];
}

const items = $input.all();

// Build a structured report from all merged data
const userStats = items[0]?.json || {};
const subscriptions = items[1]?.json || {};
const topLessons = items[2]?.json || {};
const contributions = items[3]?.json || {};
const teachers = items[4]?.json || {};
const analytics = items[5]?.json || {};
const social = items[6]?.json || {};

const weekStart = new Date(new Date().setDate(new Date().getDate() - 7)).toISOString().split('T')[0];
const weekEnd = new Date().toISOString().split('T')[0];

const report = {
  reportPeriod: `${weekStart} to ${weekEnd}`,
  generatedAt: new Date().toISOString(),
  userMetrics: {
    totalUsers: userStats.totalUsers?.[0]?.count || 0,
    newUsersThisWeek: userStats.newUsersThisWeek?.[0]?.count || 0,
    dau: userStats.dailyActiveUsers?.[0]?.count || 0,
    wau: userStats.weeklyActiveUsers?.[0]?.count || 0,
    mau: userStats.monthlyActiveUsers?.[0]?.count || 0,
    roleBreakdown: userStats.roleBreakdown || [],
    topCities: userStats.cityBreakdown || []
  },
  subscriptionMetrics: {
    freeToProConversions: subscriptions.freeToProThisWeek?.[0]?.count || 0,
    freeToPremiumConversions: subscriptions.freeToPremiumThisWeek?.[0]?.count || 0,
    planDistribution: subscriptions.planDistribution || [],
    expiringNextWeek: subscriptions.expiringNextWeek?.[0]?.count || 0
  },
  contentMetrics: {
    topLessons: topLessons || [],
    newContributions: contributions.newContributions?.[0]?.count || 0,
    contributionStatus: contributions.statusBreakdown || [],
    topContributors: contributions.topContributors || []
  },
  teacherMetrics: teachers || [],
  webAnalytics: analytics,
  socialMedia: social
};

return [{ json: report }];

const report = $('Structure Report Data').first().json;
const aiAnalysis = $json.message?.content || $json.text || 'AI analysis unavailable';

const metrics = report.userMetrics;
const subs = report.subscriptionMetrics;
const content = report.contentMetrics;

const html = `
<!DOCTYPE html>
<html dir="ltr" lang="en">
<head>
  <meta charset="UTF-8">
  <title>Darsy Weekly Growth Report - ${report.reportPeriod}</title>
  <style>
    body { font-family: 'Segoe UI', Arial, sans-serif; margin: 0; padding: 20px; background: #f5f7fa; color: #333; }
    .container { max-width: 800px; margin: 0 auto; background: white; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.08); }
    .header { background: linear-gradient(135deg, #6366f1, #8b5cf6); color: white; padding: 30px; text-align: center; }
    .header h1 { margin: 0; font-size: 24px; }
    .header p { margin: 8px 0 0; opacity: 0.85; font-size: 14px; }
    .metrics-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: #e5e7eb; }
    .metric-card { background: white; padding: 20px; text-align: center; }
    .metric-value { font-size: 28px; font-weight: 700; color: #6366f1; }
    .metric-label { font-size: 12px; color: #6b7280; text-transform: uppercase; margin-top: 4px; }
    .section { padding: 24px 30px; border-bottom: 1px solid #f0f0f0; }
    .section h2 { font-size: 18px; color: #1f2937; margin: 0 0 16px; }
    .ai-analysis { background: #faf5ff; border-left: 4px solid #8b5cf6; padding: 16px; border-radius: 0 8px 8px 0; white-space: pre-wrap; line-height: 1.6; font-size: 14px; }
    .lessons-table { width: 100%; border-collapse: collapse; font-size: 14px; }
    .lessons-table th { background: #f9fafb; padding: 10px; text-align: left; font-weight: 600; }
    .lessons-table td { padding: 10px; border-top: 1px solid #f0f0f0; }
    .badge { display: inline-block; padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 600; }
    .badge-green { background: #dcfce7; color: #166534; }
    .badge-blue { background: #dbeafe; color: #1e40af; }
    .badge-amber { background: #fef3c7; color: #92400e; }
    .footer { padding: 20px 30px; text-align: center; color: #9ca3af; font-size: 12px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Darsy Weekly Growth Report</h1>
      <p>${report.reportPeriod} | Generated ${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</p>
    </div>

    <div class="metrics-grid">
      <div class="metric-card">
        <div class="metric-value">${metrics.totalUsers.toLocaleString()}</div>
        <div class="metric-label">Total Users</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">+${metrics.newUsersThisWeek}</div>
        <div class="metric-label">New This Week</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">${metrics.dau}</div>
        <div class="metric-label">Daily Active</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">${metrics.wau}</div>
        <div class="metric-label">Weekly Active</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">${metrics.mau}</div>
        <div class="metric-label">Monthly Active</div>
      </div>
      <div class="metric-card">
        <div class="metric-value">${metrics.wau > 0 ? ((metrics.dau / metrics.wau) * 100).toFixed(1) : 0}%</div>
        <div class="metric-label">DAU/WAU Ratio</div>
      </div>
    </div>

    <div class="section">
      <h2>Subscription Conversions</h2>
      <p><span class="badge badge-green">+${subs.freeToPremiumConversions}</span> Free to Premium &nbsp; <span class="badge badge-blue">+${subs.freeToProConversions}</span> Free to Pro &nbsp; <span class="badge badge-amber">${subs.expiringNextWeek} expiring soon</span></p>
    </div>

    <div class="section">
      <h2>Top Lessons This Week</h2>
      <table class="lessons-table">
        <tr><th>#</th><th>Lesson</th><th>Views</th><th>Unique Users</th></tr>
        ${(content.topLessons || []).map((l, i) => `<tr><td>${i+1}</td><td>${l.title || l.lessonId || 'Unknown'}</td><td>${l.views}</td><td>${l.uniqueUserCount}</td></tr>`).join('')}
      </table>
    </div>

    <div class="section">
      <h2>Contributions</h2>
      <p><strong>${content.newContributions}</strong> new contributions this week</p>
    </div>

    <div class="section">
      <h2>AI Executive Analysis</h2>
      <div class="ai-analysis">${aiAnalysis}</div>
    </div>

    <div class="footer">
      <p>Darsy Growth Dashboard | Auto-generated by n8n</p>
    </div>
  </div>
</body>
</html>`;

return [{ json: { html, reportData: report, aiAnalysis } }];

